import pytest
from fastapi.testclient import TestClient

from backend.main import app

client = TestClient(app)


def test_post_api_events_rejects_empty_body():
    assert client.post('/api/events', json={}).status_code == 422


def test_post_api_events_rejects_missing_name():
    assert client.post('/api/events', json={'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_missing_category():
    assert client.post('/api/events', json={'name': 'Sample name', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_missing_venue():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_missing_date():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_missing_start_time():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'capacity': 100, 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_missing_capacity():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_non_numeric_capacity():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 'not a number', 'entry_fee': 0.0}).status_code == 422


def test_post_api_events_rejects_missing_entry_fee():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100}).status_code == 422


def test_post_api_events_rejects_non_numeric_entry_fee():
    assert client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 'not a number'}).status_code == 422


def test_posted_item_shows_up_in_the_list():
    r = client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0})
    assert r.status_code < 300, r.text
    items = client.get('/api/events').json()['items']
    assert len(items) == 1
    for k, v in {'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0}.items():
        if k in items[0]:
            assert items[0][k] == (pytest.approx(v) if isinstance(v, (int, float)) and not isinstance(v, bool) else v)


def test_put_api_events_id_updates_the_item():
    r = client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0})
    assert r.status_code < 300, r.text
    seed = r.json()
    r = client.put(f"/api/events/{seed['id']}", json={'name': 'Sample name v2', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0})
    assert r.status_code == 200, r.text
    items = client.get('/api/events').json()['items']
    assert len(items) == 1
    assert items[0]['name'] == 'Sample name v2'


def test_delete_api_events_id_removes_the_item():
    r = client.post('/api/events', json={'name': 'Sample name', 'category': 'Coding', 'venue': 'Sample venue', 'date': '2026-01-15', 'start_time': '10:30', 'capacity': 100, 'entry_fee': 0.0})
    assert r.status_code < 300, r.text
    seed = r.json()
    r = client.delete(f"/api/events/{seed['id']}")
    assert r.status_code == 200, r.text
    assert client.get('/api/events').json()['items'] == []
